@Configuration
public class UserRouterConfig {

    @Bean
    public RouterFunction<ServerResponse> userRoutes(UserHandler userHandler) {
        return route()
            .GET("/api/v1/users/{id}", accept(MediaType.APPLICATION_JSON), userHandler::getUserById)
            .POST("/api/v1/users", accept(MediaType.APPLICATION_JSON), userHandler::createUser)
            .filter((request, next) -> {
                long startTime = System.currentTimeMillis();
                return next.handle(request)
                    .doOnSuccess(response -> log.info("Path: {}, Status: {}, Duration: {}ms", 
                        request.path(), response.statusCode(), System.currentTimeMillis() - startTime));
            })
            .build();
    }
}
